/* ---------- Reset & tokens ---------- */
*,*::before,*::after{box-sizing:border-box}
html,body{margin:0;padding:0}
:root{
  --bg:#0a0a0c;
  --bg-1:#0f0f12;
  --bg-2:#15151a;
  --bg-3:#1c1c22;
  --line:#26262e;
  --line-2:#33333d;
  --text:#ececf1;
  --muted:#8a8a96;
  --muted-2:#5a5a66;
  --accent:#d4ff3a;        /* electric lime */
  --accent-2:#ff5b3a;      /* alarm orange */
  --gold:#c8a96a;
  --radius:14px;
  --radius-sm:8px;
  --shadow:0 30px 60px -20px rgba(0,0,0,.6), 0 8px 20px -10px rgba(0,0,0,.5);
  --serif:'Playfair Display', Georgia, serif;
  --sans:'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}
html{scroll-behavior:smooth}
body{
  background:var(--bg);
  color:var(--text);
  font-family:var(--sans);
  font-size:15px;
  line-height:1.55;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}

.container{
  width:100%;
  max-width:1320px;
  margin:0 auto;
  padding:0 28px;
}
.section{padding:96px 0}
.kicker{
  font-size:11px;letter-spacing:.22em;text-transform:uppercase;
  color:var(--muted);margin:0 0 10px;font-weight:500;
}
.kicker.accent-text{color:var(--accent)}
.muted{color:var(--muted)}
h1,h2,h3,h4{font-family:var(--serif);font-weight:600;letter-spacing:-.01em;margin:0}
h2{font-size:clamp(28px,4vw,48px);line-height:1.05}
h3{font-size:clamp(22px,2.4vw,32px);line-height:1.15}
h4{font-size:18px;line-height:1.3}
.italic{font-style:italic;color:var(--accent);font-weight:500}

.section-head{
  display:flex;align-items:flex-end;justify-content:space-between;
  gap:24px;margin-bottom:48px;flex-wrap:wrap;
}
.link-arrow{
  color:var(--muted);font-size:13px;letter-spacing:.05em;
  border-bottom:1px solid var(--line-2);padding-bottom:4px;
  transition:color .2s, border-color .2s;
}
.link-arrow:hover{color:var(--accent);border-color:var(--accent)}

.btn{
  display:inline-flex;align-items:center;gap:8px;
  padding:14px 26px;border-radius:999px;
  font-size:13px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;
  transition:transform .2s ease, background .2s, color .2s, border-color .2s;
  white-space:nowrap;cursor:pointer;
}
.btn.small{padding:10px 18px;font-size:11px}
.btn-primary{
  background:var(--accent);color:#0a0a0c;
}
.btn-primary:hover{background:#fff;transform:translateY(-1px)}
.btn-ghost{
  background:transparent;color:var(--text);
  border:1px solid var(--line-2);
}
.btn-ghost:hover{border-color:var(--accent);color:var(--accent)}

.badge{
  display:inline-block;padding:4px 8px;border-radius:4px;
  font-size:10px;font-weight:700;letter-spacing:.1em;
  background:var(--bg-3);color:var(--text);
}
.badge-red{background:var(--accent-2);color:#0a0a0c}

/* ---------- Announcement ---------- */
.announcement{
  background:linear-gradient(90deg,#0a0a0c,#15151a,#0a0a0c);
  border-bottom:1px solid var(--line);
  overflow:hidden;font-size:11px;letter-spacing:.18em;text-transform:uppercase;
  color:var(--muted);
}
.announcement-track{
  display:flex;gap:48px;padding:10px 0;
  white-space:nowrap;
  animation:marquee 38s linear infinite;
}
@keyframes marquee{
  0%{transform:translateX(0)}
  100%{transform:translateX(-50%)}
}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:50;
  background:rgba(10,10,12,.78);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  border-bottom:1px solid var(--line);
}
.header-inner{
  display:flex;align-items:center;gap:24px;
  height:72px;
}
.brand{
  font-family:var(--serif);font-size:24px;font-weight:700;
  letter-spacing:.04em;
}
.brand span{color:var(--accent)}
.menu-btn{display:none}
.primary-nav{display:flex;gap:28px;margin-left:24px}
.primary-nav a{
  font-size:13px;font-weight:500;color:var(--text);
  position:relative;padding:6px 0;
}
.primary-nav a::after{
  content:'';position:absolute;left:0;right:100%;bottom:0;height:1px;
  background:var(--accent);transition:right .25s ease;
}
.primary-nav a:hover::after{right:0}
.primary-nav a.accent{color:var(--accent-2)}
.header-actions{margin-left:auto;display:flex;align-items:center;gap:6px}
.icon-btn{
  width:40px;height:40px;border-radius:999px;
  display:inline-flex;align-items:center;justify-content:center;
  color:var(--text);transition:background .2s, color .2s;
  position:relative;
}
.icon-btn:hover{background:var(--bg-2);color:var(--accent)}
.cart-count{
  position:absolute;top:4px;right:4px;
  background:var(--accent);color:#0a0a0c;
  font-size:10px;font-weight:700;
  width:16px;height:16px;border-radius:999px;
  display:flex;align-items:center;justify-content:center;
}

/* ---------- HERO ---------- */
.hero{
  position:relative;
  min-height:84vh;
  padding:120px 0 80px;
  overflow:hidden;
  isolation:isolate;
}
.hero-bg{
  position:absolute;inset:0;z-index:-2;
  background:
    radial-gradient(1200px 500px at 80% 20%, rgba(212,255,58,.08), transparent 60%),
    radial-gradient(900px 600px at 10% 90%, rgba(255,91,58,.07), transparent 60%),
    linear-gradient(180deg,#0a0a0c 0%,#0f0f12 100%);
}
.hero-grid{
  position:absolute;inset:0;z-index:-1;opacity:.5;
  background-image:
    linear-gradient(var(--line) 1px, transparent 1px),
    linear-gradient(90deg, var(--line) 1px, transparent 1px);
  background-size:80px 80px;
  mask-image:radial-gradient(ellipse 70% 70% at 50% 50%, #000 30%, transparent 75%);
  -webkit-mask-image:radial-gradient(ellipse 70% 70% at 50% 50%, #000 30%, transparent 75%);
}
.hero-content{position:relative;max-width:780px}
.hero-eyebrow{
  display:inline-block;padding:6px 14px;border-radius:999px;
  border:1px solid var(--line-2);background:rgba(20,20,24,.6);
  font-size:11px;letter-spacing:.22em;text-transform:uppercase;
  color:var(--muted);margin-bottom:28px;
}
.hero-title{
  font-family:var(--serif);font-weight:500;
  font-size:clamp(48px, 8.5vw, 124px);
  line-height:.95;letter-spacing:-.02em;
  margin:0 0 28px;
}
.hero-sub{
  font-size:17px;color:var(--muted);
  max-width:520px;margin:0 0 36px;
}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:64px}
.hero-meta{
  display:flex;gap:48px;padding-top:32px;
  border-top:1px solid var(--line);max-width:520px;
}
.hero-meta div{display:flex;flex-direction:column}
.hero-meta strong{font-family:var(--serif);font-size:24px;font-weight:600}
.hero-meta span{font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);margin-top:4px}

/* Floating product callout */
.hero-product{
  position:absolute;right:6%;top:24%;
  width:280px;padding:20px;border-radius:var(--radius);
  background:linear-gradient(180deg, rgba(28,28,34,.85), rgba(15,15,18,.85));
  backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);
  border:1px solid var(--line-2);
  box-shadow:var(--shadow);
  transform:rotate(2deg);
}
.hero-product::before{
  content:'';display:block;height:280px;border-radius:10px;margin-bottom:16px;
  background:
    radial-gradient(circle at 30% 30%, rgba(212,255,58,.18), transparent 50%),
    linear-gradient(160deg,#1c1c22, #0f0f12 70%);
  border:1px solid var(--line);
  position:relative;
}
.hp-tag{
  font-size:10px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--accent);margin-bottom:6px;
}
.hp-name{font-family:var(--serif);font-size:20px;margin-bottom:4px}
.hp-price{color:var(--muted);font-size:14px}

@media (max-width:1100px){
  .hero-product{display:none}
}

/* ---------- Logo strip ---------- */
.logo-strip{
  border-top:1px solid var(--line);
  border-bottom:1px solid var(--line);
  background:#0c0c0f;
}
.logo-row{
  display:flex;justify-content:space-between;align-items:center;
  padding:28px 0;flex-wrap:wrap;gap:24px;
}
.logo-row span{
  font-family:var(--serif);font-style:italic;
  color:var(--muted-2);font-size:18px;letter-spacing:.1em;
  transition:color .2s;
}
.logo-row span:hover{color:var(--text)}

/* ---------- Categories ---------- */
.category-grid{
  display:grid;
  grid-template-columns:repeat(4, 1fr);
  grid-template-rows:240px 240px;
  gap:16px;
}
.cat-card{
  position:relative;border-radius:var(--radius);overflow:hidden;
  background:var(--bg-2);border:1px solid var(--line);
  transition:transform .4s ease, border-color .3s;
  display:block;
}
.cat-card:hover{transform:translateY(-4px);border-color:var(--line-2)}
.cat-lg{grid-row:span 2; grid-column:span 2}
.cat-art{
  position:absolute;inset:0;transition:transform .8s ease;
}
.cat-card:hover .cat-art{transform:scale(1.06)}

.cat-art[data-art="outer"]{
  background:
    radial-gradient(circle at 60% 35%, rgba(212,255,58,.12), transparent 50%),
    linear-gradient(160deg, #1f1f26 0%, #0a0a0c 100%);
}
.cat-art[data-art="outer"]::after{
  content:'';position:absolute;left:50%;top:50%;
  width:180px;height:280px;transform:translate(-50%,-50%);
  background:linear-gradient(180deg,#2a2a32,#15151a);
  border-radius:90px 90px 30px 30px;
  box-shadow:inset 0 -40px 60px rgba(0,0,0,.5), 0 30px 60px rgba(0,0,0,.4);
}
.cat-art[data-art="knit"]{
  background:
    repeating-linear-gradient(45deg, #1c1c22 0 6px, #15151a 6px 12px),
    #15151a;
}
.cat-art[data-art="denim"]{
  background:
    repeating-linear-gradient(0deg, rgba(255,255,255,.02) 0 2px, transparent 2px 4px),
    linear-gradient(160deg, #1a2332 0%, #0e1420 100%);
}
.cat-art[data-art="acc"]{
  background:
    radial-gradient(circle at 30% 70%, rgba(200,169,106,.2), transparent 50%),
    linear-gradient(160deg, #1c1c22, #0a0a0c);
}
.cat-art[data-art="acc"]::after{
  content:'';position:absolute;left:50%;top:50%;
  width:120px;height:120px;border-radius:999px;
  transform:translate(-50%,-50%);
  border:14px solid var(--gold);
  box-shadow:0 20px 40px rgba(0,0,0,.5);
}
.cat-art[data-art="foot"]{
  background:linear-gradient(160deg, #20201f, #0a0a0c);
}
.cat-art[data-art="foot"]::after{
  content:'';position:absolute;left:50%;top:55%;
  width:200px;height:70px;transform:translate(-50%,-50%) rotate(-8deg);
  background:linear-gradient(180deg,#2a2a30,#15151a);
  border-radius:50% 60% 30% 70%/60% 50% 50% 60%;
  box-shadow:0 30px 50px rgba(0,0,0,.5);
}

.cat-meta{
  position:absolute;left:20px;bottom:20px;right:20px;
  display:flex;justify-content:space-between;align-items:flex-end;
  font-family:var(--serif);
}
.cat-meta span{font-size:22px}
.cat-lg .cat-meta span{font-size:32px}
.cat-meta em{
  font-style:normal;font-family:var(--sans);
  font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);
}

/* ---------- Featured products ---------- */
.filter-tabs{display:flex;gap:6px;background:var(--bg-2);padding:6px;border-radius:999px;border:1px solid var(--line)}
.tab{
  padding:8px 18px;border-radius:999px;font-size:12px;font-weight:500;
  color:var(--muted);transition:.2s;letter-spacing:.05em;
}
.tab:hover{color:var(--text)}
.tab.active{background:var(--text);color:var(--bg)}

.product-grid{
  display:grid;grid-template-columns:repeat(4,1fr);gap:24px;
}
.product{
  position:relative;border-radius:var(--radius);overflow:hidden;
  background:var(--bg-1);border:1px solid var(--line);
  transition:transform .35s ease, border-color .25s;
  display:flex;flex-direction:column;
}
.product:hover{transform:translateY(-6px);border-color:var(--line-2)}
.p-art{
  position:relative;height:340px;
  background:linear-gradient(160deg, var(--c1, #1c1c22), var(--c2, #0a0a0c));
  overflow:hidden;
}
.p-art::after{
  content:'';position:absolute;left:50%;top:50%;
  transform:translate(-50%,-50%);
  width:65%;height:78%;
  background:var(--shape, linear-gradient(180deg,#2a2a32,#15151a));
  border-radius:var(--shapeRadius, 12px);
  box-shadow:inset 0 -30px 60px rgba(0,0,0,.4), 0 30px 50px rgba(0,0,0,.3);
}
.p-tags{
  position:absolute;top:14px;left:14px;display:flex;flex-direction:column;gap:6px;z-index:2;
}
.p-fav{
  position:absolute;top:14px;right:14px;z-index:2;
  width:36px;height:36px;border-radius:999px;
  background:rgba(10,10,12,.6);backdrop-filter:blur(8px);
  display:flex;align-items:center;justify-content:center;color:var(--text);
  border:1px solid var(--line);transition:.2s;
}
.p-fav:hover{background:var(--accent);color:#0a0a0c;border-color:var(--accent)}
.p-quick{
  position:absolute;left:14px;right:14px;bottom:14px;z-index:2;
  padding:12px;border-radius:999px;text-align:center;
  background:var(--text);color:var(--bg);font-size:12px;font-weight:600;
  letter-spacing:.1em;text-transform:uppercase;
  opacity:0;transform:translateY(8px);transition:.3s;
}
.product:hover .p-quick{opacity:1;transform:translateY(0)}
.p-body{padding:20px;display:flex;flex-direction:column;gap:8px}
.p-cat{font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted)}
.p-name{font-family:var(--serif);font-size:18px;color:var(--text)}
.p-row{display:flex;justify-content:space-between;align-items:center;margin-top:6px}
.p-price{font-size:16px;font-weight:600}
.p-price .strike{color:var(--muted);text-decoration:line-through;font-weight:400;margin-left:8px;font-size:14px}
.p-swatches{display:flex;gap:6px}
.sw{width:14px;height:14px;border-radius:999px;border:1px solid var(--line-2)}
.p-rate{font-size:12px;color:var(--muted)}
.p-rate b{color:var(--text);font-weight:600}

/* ---------- Deals ---------- */
.deals{background:linear-gradient(180deg,#0a0a0c,#0c0c10)}
.deals-head{
  display:flex;justify-content:space-between;align-items:flex-end;
  gap:24px;flex-wrap:wrap;margin-bottom:48px;
}
.countdown{
  display:flex;align-items:center;gap:6px;
  background:var(--bg-2);border:1px solid var(--line);
  padding:14px 18px;border-radius:var(--radius);
}
.countdown div{display:flex;flex-direction:column;align-items:center;min-width:48px}
.countdown b{font-family:var(--serif);font-size:28px;font-weight:600;color:var(--accent)}
.countdown span{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);margin-top:2px}
.cd-sep{font-family:var(--serif);font-size:24px;color:var(--muted-2);align-self:flex-start;padding-top:6px}

.deals-grid{
  display:grid;grid-template-columns:1.4fr 1fr;gap:24px;
}
.deal-hero{
  position:relative;border-radius:var(--radius);overflow:hidden;
  background:var(--bg-1);border:1px solid var(--line);
  display:flex;flex-direction:column;min-height:520px;
}
.deal-art{flex:1;position:relative;overflow:hidden}
.deal-art-1{
  background:
    radial-gradient(circle at 70% 30%, rgba(255,91,58,.18), transparent 50%),
    radial-gradient(circle at 20% 70%, rgba(212,255,58,.08), transparent 50%),
    linear-gradient(160deg, #1f1a18, #0a0a0c);
}
.deal-art-1::after{
  content:'';position:absolute;left:50%;top:50%;
  transform:translate(-50%,-50%);
  width:60%;height:70%;
  background:linear-gradient(180deg,#2a2a32,#15151a);
  border-radius:50% 50% 14px 14px/30% 30% 14px 14px;
  box-shadow:inset 0 -40px 80px rgba(0,0,0,.5), 0 40px 70px rgba(0,0,0,.5);
}
.deal-body{padding:36px;background:var(--bg-1);border-top:1px solid var(--line)}
.deal-body h3{margin:14px 0 12px;font-size:34px;line-height:1.05}
.deal-body p{color:var(--muted);max-width:480px;margin:0 0 22px}
.deal-row{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.stock{font-size:12px;color:var(--accent);letter-spacing:.05em}

.deal-list{display:flex;flex-direction:column;gap:14px}
.deal-mini{
  display:grid;grid-template-columns:120px 1fr;gap:18px;
  background:var(--bg-1);border:1px solid var(--line);
  border-radius:var(--radius);padding:14px;align-items:center;
  transition:border-color .2s, transform .2s;
}
.deal-mini:hover{border-color:var(--line-2);transform:translateX(4px)}
.dm-art{
  height:96px;border-radius:10px;
  background:linear-gradient(160deg,#1c1c22,#0a0a0c);
  position:relative;overflow:hidden;
}
.dm-art::after{
  content:'';position:absolute;left:50%;top:50%;
  transform:translate(-50%,-50%);
  width:60%;height:70%;
  background:linear-gradient(180deg,#2a2a32,#15151a);
  border-radius:8px;
  box-shadow:inset 0 -10px 20px rgba(0,0,0,.4);
}
.dm-1{background:linear-gradient(160deg,#1c1c22,#0a0a0c)}
.dm-2{background:linear-gradient(160deg,#1c1814,#0a0807)}
.dm-3{background:linear-gradient(160deg,#1a1f24,#0a0c0e)}
.dm-4{background:linear-gradient(160deg,#1a2030,#0a0c14)}
.dm-body h4{margin-bottom:6px}
.price-row{display:flex;align-items:center;gap:8px;margin-bottom:8px}
.price{font-weight:700;font-size:16px}
.strike{color:var(--muted);text-decoration:line-through;font-size:13px}
.bar{height:4px;background:var(--bg-3);border-radius:999px;overflow:hidden;margin-bottom:4px}
.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent-2));border-radius:999px}
.dm-body small{color:var(--muted);font-size:11px;letter-spacing:.05em}

/* ---------- Editorial ---------- */
.editorial-feature{
  display:grid;grid-template-columns:1.1fr 1fr;gap:32px;
  border-radius:var(--radius);overflow:hidden;
  background:var(--bg-1);border:1px solid var(--line);
  margin-bottom:48px;
}
.ef-art{
  min-height:480px;
  background:
    radial-gradient(circle at 30% 30%, rgba(200,169,106,.15), transparent 55%),
    radial-gradient(circle at 70% 80%, rgba(255,91,58,.08), transparent 55%),
    linear-gradient(160deg,#1a1816,#0a0a0c);
  position:relative;
}
.ef-art::after{
  content:'';position:absolute;left:50%;top:50%;
  width:65%;height:75%;transform:translate(-50%,-50%) rotate(-2deg);
  background:
    repeating-linear-gradient(90deg, rgba(255,255,255,.03) 0 2px, transparent 2px 6px),
    linear-gradient(180deg,#28231e,#15120f);
  border-radius:10px;
  box-shadow:inset 0 -50px 80px rgba(0,0,0,.5), 0 40px 80px rgba(0,0,0,.5);
}
.ef-body{padding:48px;display:flex;flex-direction:column;justify-content:center}
.ef-tag{
  font-size:11px;letter-spacing:.22em;text-transform:uppercase;
  color:var(--accent);margin-bottom:18px;
}
.ef-body h3{font-size:38px;line-height:1.05;margin-bottom:18px}
.ef-body p{color:var(--muted);margin:0 0 32px}
.ef-meta{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.avatar{
  width:44px;height:44px;border-radius:999px;
  background:radial-gradient(circle at 40% 35%, #5a5a66, #1c1c22);
  border:1px solid var(--line-2);
}
.ef-meta strong{display:block;font-family:var(--sans);font-size:13px}
.ef-meta span{font-size:12px;color:var(--muted)}
.ef-meta .btn{margin-left:auto}

.editorial-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.post{
  border-radius:var(--radius);overflow:hidden;
  background:var(--bg-1);border:1px solid var(--line);
  padding:0 0 22px;transition:transform .3s, border-color .3s;
  cursor:pointer;
}
.post:hover{transform:translateY(-4px);border-color:var(--line-2)}
.post-art{height:220px;position:relative}
.p-1{background:radial-gradient(circle at 50% 50%, #2a2a32, #0a0a0c);}
.p-2{background:linear-gradient(160deg, #1a2620, #0a0e0c);}
.p-3{background:radial-gradient(circle at 60% 40%, #2a2228, #0a0a0c);}
.post-tag{
  display:inline-block;font-size:10px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--accent);margin:18px 22px 8px;
}
.post h4{padding:0 22px;font-size:18px;line-height:1.3;margin-bottom:10px}
.post small{padding:0 22px;color:var(--muted);font-size:12px;letter-spacing:.05em}

/* ---------- Values ---------- */
.values{padding:64px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:#0c0c10}
.values-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:32px}
.value{display:flex;flex-direction:column;gap:8px}
.v-icon{
  font-size:28px;color:var(--accent);
  width:48px;height:48px;border-radius:12px;
  background:var(--bg-2);border:1px solid var(--line);
  display:flex;align-items:center;justify-content:center;margin-bottom:8px;
}
.value h4{font-family:var(--sans);font-size:15px;font-weight:600}
.value p{margin:0;color:var(--muted);font-size:14px}

/* ---------- Newsletter ---------- */
.newsletter{padding:96px 0;position:relative;overflow:hidden}
.newsletter::before{
  content:'';position:absolute;inset:0;z-index:-1;
  background:
    radial-gradient(800px 400px at 80% 50%, rgba(212,255,58,.08), transparent 60%),
    radial-gradient(600px 300px at 10% 80%, rgba(255,91,58,.06), transparent 60%),
    linear-gradient(180deg,#0a0a0c,#0f0f12);
}
.nl-inner{
  display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center;
}
.nl-inner h2{font-size:clamp(32px,4.5vw,56px);line-height:1}
.nl-inner p{color:var(--muted);margin-top:18px;max-width:420px}
.nl-form{
  display:flex;gap:10px;flex-wrap:wrap;
  background:var(--bg-2);border:1px solid var(--line);
  border-radius:999px;padding:8px;align-items:center;
  position:relative;
}
.nl-form input{
  flex:1;min-width:200px;background:none;border:0;outline:none;
  color:var(--text);padding:14px 20px;font-size:15px;
}
.nl-form input::placeholder{color:var(--muted-2)}
#nlMsg{
  position:absolute;top:calc(100% + 10px);left:20px;
  font-size:12px;color:var(--accent);
}

/* ---------- Footer ---------- */
.site-footer{
  background:#06060a;border-top:1px solid var(--line);
  padding:72px 0 32px;
}
.footer-inner{
  display:grid;grid-template-columns:1.2fr 2.5fr;gap:48px;
  padding-bottom:48px;border-bottom:1px solid var(--line);
}
.footer-brand p{color:var(--muted);margin:18px 0 24px;font-size:14px}
.socials{display:flex;gap:8px}
.socials a{
  width:40px;height:40px;border-radius:999px;border:1px solid var(--line-2);
  display:flex;align-items:center;justify-content:center;
  font-size:11px;font-weight:700;letter-spacing:.05em;color:var(--muted);
  transition:.2s;
}
.socials a:hover{background:var(--accent);color:#0a0a0c;border-color:var(--accent)}
.footer-cols{display:grid;grid-template-columns:repeat(4,1fr);gap:32px}
.footer-cols h5{
  font-family:var(--sans);font-size:11px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--muted);margin:0 0 18px;font-weight:600;
}
.footer-cols a{
  display:block;color:var(--text);font-size:14px;
  padding:6px 0;transition:color .2s;
}
.footer-cols a:hover{color:var(--accent)}
.footer-bottom{
  display:flex;justify-content:space-between;
  padding-top:24px;color:var(--muted);font-size:12px;letter-spacing:.05em;
}

/* ---------- Responsive ---------- */
@media (max-width:1080px){
  .product-grid{grid-template-columns:repeat(3,1fr)}
  .category-grid{grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,200px)}
  .cat-lg{grid-row:span 2;grid-column:span 2}
  .deals-grid{grid-template-columns:1fr}
  .editorial-feature{grid-template-columns:1fr}
  .ef-art{min-height:320px}
  .footer-inner{grid-template-columns:1fr}
  .footer-cols{grid-template-columns:repeat(4,1fr)}
}
@media (max-width:840px){
  .section{padding:72px 0}
  .primary-nav{display:none}
  .menu-btn{display:inline-flex}
  .product-grid{grid-template-columns:repeat(2,1fr)}
  .category-grid{grid-template-columns:repeat(2,1fr);grid-template-rows:auto;}
  .cat-lg{grid-column:span 2;grid-row:auto;height:280px}
  .cat-card{height:200px}
  .editorial-grid{grid-template-columns:1fr}
  .values-grid{grid-template-columns:repeat(2,1fr)}
  .footer-cols{grid-template-columns:repeat(2,1fr)}
  .nl-inner{grid-template-columns:1fr;gap:24px}
  .ef-body{padding:32px 24px}
  .deal-body{padding:28px 24px}
  .deal-body h3{font-size:26px}
  .hero{min-height:auto;padding:80px 0 60px}
  .hero-meta{gap:24px;flex-wrap:wrap}
}
@media (max-width:480px){
  .product-grid{grid-template-columns:1fr}
  .countdown b{font-size:22px}
  .countdown div{min-width:36px}
  .footer-bottom{flex-direction:column;gap:8px}
  .deal-mini{grid-template-columns:88px 1fr}
}

