function renderProducts(filter='all'){
  const grid = document.getElementById('productGrid');
  const list = filter === 'all' ? PRODUCTS : PRODUCTS.filter(p => p.tags.includes(filter));
  grid.innerHTML = list.map(p => {
    const s = SHAPE_CSS[p.shape] || SHAPE_CSS.coat;
    const tags = p.badges.map(b => {
      const cls = b.startsWith('-') ? 'badge badge-red' : 'badge';
      return `<span class="${cls}">${b}</span>`;
    }).join('');
    const swatches = p.colors.map(c => `<span class="sw" style="background:${c}"></span>`).join('');
    const priceHtml = p.was
      ? `<span class="p-price">$${p.price}<span class="strike">$${p.was}</span></span>`
      : `<span class="p-price">$${p.price}</span>`;
    return `
      <article class="product" data-tags="${p.tags.join(' ')}">
        <div class="p-art" style="--c1:${s.c1};--c2:${s.c2};--shape:${s.shape};--shapeRadius:${s.radius}">
          <div class="p-tags">${tags}</div>
          <button class="p-fav" aria-label="Save">
            <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6">
              <path d="M12 21s-7-4.5-9.3-9A5.3 5.3 0 0 1 12 6a5.3 5.3 0 0 1 9.3 6C19 16.5 12 21 12 21Z"/>
            </svg>
          </button>
          <div class="p-quick">Quick add +</div>
        </div>
        <div class="p-body">
          <span class="p-cat">${p.cat}</span>
          <span class="p-name">${p.name}</span>
          <div class="p-row">
            ${priceHtml}
            <span class="p-rate">★ <b>${p.rating}</b> (${p.reviews})</span>
          </div>
          <div class="p-row">
            <div class="p-swatches">${swatches}</div>
          </div>
        </div>
      </article>`;
  }).join('');
}

/* ---------- Filter tabs ---------- */
document.querySelectorAll('.tab').forEach(t => {
  t.addEventListener('click', () => {
    document.querySelectorAll('.tab').forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    renderProducts(t.dataset.filter);
  });
});

/* ---------- Quick add → cart ---------- */
document.addEventListener('click', e => {
  if (e.target.closest('.p-quick')) {
    const el = document.querySelector('.cart-count');
    el.textContent = parseInt(el.textContent || '0', 10) + 1;
    el.animate(
      [{ transform:'scale(1)' }, { transform:'scale(1.4)' }, { transform:'scale(1)' }],
      { duration: 400, easing: 'ease-out' }
    );
  }
  if (e.target.closest('.p-fav')) {
    const btn = e.target.closest('.p-fav');
    btn.style.background = btn.style.background.includes('212') ? '' : 'var(--accent)';
    btn.style.color = btn.style.color === 'rgb(10, 10, 12)' ? '' : '#0a0a0c';
  }
});

/* ---------- Countdown ---------- */
(function startCountdown(){
  // 2 days 8h from now (rolling)
  const target = Date.now() + (2 * 24 + 8) * 3600 * 1000;
  const pad = n => String(Math.max(0, n)).padStart(2, '0');
  const d = document.getElementById('cd-d');
  const h = document.getElementById('cd-h');
  const m = document.getElementById('cd-m');
  const s = document.getElementById('cd-s');
  function tick(){
    const diff = Math.max(0, target - Date.now());
    const days = Math.floor(diff / 86400000);
    const hrs  = Math.floor(diff / 3600000) % 24;
    const mins = Math.floor(diff / 60000) % 60;
    const secs = Math.floor(diff / 1000) % 60;
    d.textContent = pad(days);
    h.textContent = pad(hrs);
    m.textContent = pad(mins);
    s.textContent = pad(secs);
  }
  tick();
  setInterval(tick, 1000);
})();

/* ---------- Newsletter ---------- */
document.getElementById('nlForm').addEventListener('submit', e => {
  e.preventDefault();
  const msg = document.getElementById('nlMsg');
  msg.textContent = '✓ Welcome to NOIR — check your inbox for 15% off.';
  e.target.querySelector('input').value = '';
  setTimeout(() => msg.textContent = '', 6000);
});

/* ---------- Reveal on scroll ---------- */
const io = new IntersectionObserver(entries => {
  entries.forEach(en => {
    if (en.isIntersecting) {
      en.target.style.opacity = '1';
      en.target.style.transform = 'translateY(0)';
      io.unobserve(en.target);
    }
  });
}, { threshold: 0.08 });

function bindReveal(){
  document.querySelectorAll('.section, .product, .post, .deal-mini, .cat-card').forEach(el => {
    if (el.dataset.revealed) return;
    el.dataset.revealed = '1';
    el.style.opacity = '0';
    el.style.transform = 'translateY(20px)';
    el.style.transition = 'opacity .7s ease, transform .7s ease';
    io.observe(el);
  });
}

/* ---------- Init ---------- */
renderProducts('all');
bindReveal();
// rebind after product render so new cards animate
new MutationObserver(bindReveal).observe(document.getElementById('productGrid'), { childList:true });

