+
+/* ---------- Newsletter ---------- */
+.newsletter{padding:96px 0;position:relative;overflow:hidden}
+.newsletter::before{
+  content:'';position:absolute;inset:0;z-index:-1;
+  background:
+    radial-gradient(800px 400px at 80% 50%, rgba(212,255,58,.08), transparent 60%),
+    radial-gradient(600px 300px at 10% 80%, rgba(255,91,58,.06), transparent 60%),
+    linear-gradient(180deg,#0a0a0c,#0f0f12);
+}
+.nl-inner{
+  display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center;
+}
+.nl-inner h2{font-size:clamp(32px,4.5vw,56px);line-height:1}
+.nl-inner p{color:var(--muted);margin-top:18px;max-width:420px}
+.nl-form{
+  display:flex;gap:10px;flex-wrap:wrap;
